import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            if (s.charAt(i) == 'd' && i + 2 < s.length() && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't') {
                result.append('.');
                i += 3;
            } else if (s.charAt(i) == 'a' && i + 1 < s.length() && s.charAt(i + 1) == 't') {
                result.append('@');
                i += 2;
            } else {
                result.append(s.charAt(i));
                i++;
            }
        }

        String resStr = result.toString();
        StringBuilder output = new StringBuilder();

        if (!resStr.isEmpty()) {
            char firstChar = resStr.charAt(0);
            if (firstChar == '.') {
                output.append("dot");
            } else if (firstChar == '@') {
                output.append("at");
            } else {
                output.append(firstChar);
            }

            int flag = 0;
            for (int j = 1; j < resStr.length() - 1; j++) {
                char c = resStr.charAt(j);
                if (c == '@' && flag == 0) {
                    output.append(c);
                    flag = 1;
                } else if (c == '@' && flag == 1) {
                    output.append("at");
                } else {
                    output.append(c);
                }
            }

            char lastChar = resStr.charAt(resStr.length() - 1);
            if (lastChar == '.') {
                output.append("dot");
            } else if (lastChar == '@') {
                output.append("at");
            } else {
                output.append(lastChar);
            }
        }

        System.out.println(output.toString());
        sc.close();
    }
}
